CREATE TABLE IF NOT EXISTS office_agencies (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1,username TEXT UNIQUE,password_hash TEXT);
CREATE TABLE IF NOT EXISTS office_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,months INTEGER NOT NULL DEFAULT 0,price INTEGER NOT NULL DEFAULT 0,request_limit INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS office_services (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,price INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS office_subscriptions (id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL,plan_id INTEGER NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',payment_reference TEXT);
CREATE TABLE IF NOT EXISTS office_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,tracking_code TEXT NOT NULL UNIQUE,company_id INTEGER NOT NULL,agency_id INTEGER NOT NULL,service_id INTEGER,subject TEXT NOT NULL,body TEXT,write_for_me INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'new',price INTEGER NOT NULL DEFAULT 0,payment_status TEXT NOT NULL DEFAULT 'pending',payment_reference TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_events (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,actor TEXT NOT NULL,note TEXT NOT NULL,visible_to_company INTEGER NOT NULL DEFAULT 1,visible_to_agency INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_documents (id INTEGER PRIMARY KEY AUTOINCREMENT,request_id INTEGER NOT NULL,filename TEXT NOT NULL,mime TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS office_settings (key TEXT PRIMARY KEY,value TEXT NOT NULL);
